def discount_rate(amount, loyalty, coupon=False):
    rate = 0.0
    if amount >= 500:
        rate += 0.10
    if loyalty:
        rate += 0.05
    if coupon and amount >= 500:
        rate += 0.05
    return min(rate, 0.30)

for amount, loyalty, coupon in ((1200, True, False), (300, True, True), (500, False, True)):
    rate = discount_rate(amount, loyalty, coupon)
    print(f'amount={amount:>5} rate={rate:.2f} pay={amount * (1 - rate):.2f}')

