def safe_div(numerator, denominator):
    if denominator == 0:
        return None
    return numerator / denominator

def short_circuit(numerator, denominator):
    return denominator and numerator / denominator

for n, d in ((10, 2), (10, 0)):
    print(n, '/', d, '=', safe_div(n, d), '| short:', short_circuit(n, d))

