PRECEDENCE = {'+': 1, '-': 1, '*': 2, '/': 2}

def apply_op(values, ops):
    op = ops.pop()
    b, a = values.pop(), values.pop()
    if op == '+':
        values.append(a + b)
    elif op == '-':
        values.append(a - b)
    elif op == '*':
        values.append(a * b)
    else:
        values.append(a / b)

def evaluate(expr):
    values, ops, i = [], [], 0
    while i < len(expr):
        ch = expr[i]
        if ch == ' ':
            i += 1
            continue
        if ch.isdigit():
            number = ''
            while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                number += expr[i]
                i += 1
            values.append(float(number))
            continue
        if ch == '(':
            ops.append(ch)
        elif ch == ')':
            while ops and ops[-1] != '(':
                apply_op(values, ops)
            ops.pop()
        else:
            while ops and ops[-1] != '(' and PRECEDENCE[ops[-1]] >= PRECEDENCE[ch]:
                apply_op(values, ops)
            ops.append(ch)
        i += 1
    while ops:
        apply_op(values, ops)
    return values[0]

for expr in ('2 + 3 * 4', '(2 + 3) * 4', '2 + 3 * (4 - 1) / 3', '10 - 4 - 3'):
    print(f'{expr:22} = {evaluate(expr)}')

FLAGS = {'read': 1 << 0, 'write': 1 << 1, 'delete': 1 << 2, 'admin': 1 << 3}

def names_to_mask(names):
    mask = 0
    for name in names:
        mask |= FLAGS[name]
    return mask

def mask_to_names(mask):
    return [name for name, flag in FLAGS.items() if mask & flag]

def check(role, required):
    missing = required & ~role
    return missing == 0, mask_to_names(missing)

role = names_to_mask(['read', 'write'])
print('role:', mask_to_names(role), bin(role))

ok, missing = check(role, names_to_mask(['read', 'delete']))
print('can read+delete?', ok, '| missing:', missing)

ok2, missing2 = check(role, names_to_mask(['read', 'write']))
print('can read+write? ', ok2, '| missing:', missing2)

print('deny-list style:', mask_to_names(names_to_mask(['admin', 'delete']) & ~role))

BINARY = {'+': (1, 'L'), '-': (1, 'L'), '*': (2, 'L'), '/': (2, 'L'), '^': (4, 'R')}

class CalcError(ValueError):
    pass

def apply_op(values, ops):
    op = ops.pop()
    if op == 'u-':
        values.append(-values.pop())
        return
    b, a = values.pop(), values.pop()
    if op == '+':
        values.append(a + b)
    elif op == '-':
        values.append(a - b)
    elif op == '*':
        values.append(a * b)
    elif op == '/':
        if b == 0:
            raise CalcError('division by zero')
        values.append(a / b)
    else:
        values.append(a ** b)

def safe_eval(tokens):
    values, ops = [], []
    prev = 'start'
    for token in tokens:
        if token.lstrip('-').replace('.', '', 1).isdigit():
            values.append(float(token))
            prev = 'value'
            continue
        if token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                apply_op(values, ops)
            if not ops:
                raise CalcError('unbalanced parenthesis')
            ops.pop()
        else:
            if token == '-' and prev in ('start', 'op', '('):
                ops.append('u-')
                prev = 'op'
                continue
            if token not in BINARY:
                raise CalcError(f'unknown token {token!r}')
            while (ops and ops[-1] != '(' and ops[-1] != 'u-'
                   and (BINARY[ops[-1]][0] > BINARY[token][0]
                        or (BINARY[ops[-1]][0] == BINARY[token][0] and BINARY[token][1] == 'L'))):
                apply_op(values, ops)
            ops.append(token)
            prev = 'op'
    while ops:
        if ops[-1] == '(':
            raise CalcError('unbalanced parenthesis')
        apply_op(values, ops)
    if len(values) != 1:
        raise CalcError('invalid expression')
    return values[0]

for tokens in (['2', '+', '3', '*', '4'], ['-', '5', '+', '2'], ['2', '^', '3', '^', '2'], ['(', '2', '+', '3', ')', '*', '4']):
    print(' '.join(tokens), '=', safe_eval(tokens))

try:
    safe_eval(['1', '/', '0'])
except CalcError as e:
    print('CalcError:', e)

