PERMISSIONS = {
    'read': 1 << 0,
    'write': 1 << 1,
    'delete': 1 << 2,
    'publish': 1 << 3,
    'manage_users': 1 << 4,
}

ROLE_PRESETS = {
    'viewer': PERMISSIONS['read'],
    'editor': PERMISSIONS['read'] | PERMISSIONS['write'],
    'reviewer': PERMISSIONS['read'] | PERMISSIONS['publish'],
    'admin': sum(PERMISSIONS.values()),
}

def names_to_mask(names):
    mask = 0
    for name in names:
        mask |= PERMISSIONS[name]
    return mask

def mask_to_names(mask):
    return [name for name, flag in PERMISSIONS.items() if mask & flag]

def grant(mask, *names):
    return mask | names_to_mask(names)

def revoke(mask, *names):
    return mask & ~names_to_mask(names)

def check(mask, *required):
    missing = names_to_mask(required) & ~mask
    return missing == 0, mask_to_names(missing)

role = ROLE_PRESETS['editor']
print('start    :', mask_to_names(role))
role = grant(role, 'publish')
print('granted  :', mask_to_names(role))
role = revoke(role, 'write')
print('revoked  :', mask_to_names(role))

ok, missing = check(role, 'read', 'write')
print('read+write allowed?', ok, '| missing:', missing)

for name, preset in ROLE_PRESETS.items():
    ok_all, _ = check(preset, 'read')
    print(f'{name:9} bits={bin(preset):>12} can_read={ok_all}')
